// Valida la entrada del subworkflow. La URL solo puede apuntar a hosts conocidos (OWASP A10: SSRF)
const input = $input.first().json;
const contentItemId = String(input.content_item_id ?? '').trim().toLowerCase();
const imageUrl = String(input.image_url ?? '').trim();

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(contentItemId)) {
  throw new Error('validation: content_item_id no es un UUID');
}

// El sandbox de n8n 2.x no expone URL: se analiza con una expresión estricta (sin usuario, puerto ni espacios)
const match = imageUrl.match(/^https:\/\/([a-z0-9.-]+)(\/[^\s\\#]*)$/i);
if (!match) throw new Error('validation: image_url debe ser https://host/ruta, sin credenciales ni puerto');
const hostname = match[1].toLowerCase();
const pathname = match[2].split('?')[0];
if (pathname.includes('..')) throw new Error('validation: image_url no admite segmentos ..');

// Producción: Cloudinary (cuenta letiende) y archivos de Telegram. Dev agrega hosts con SGCD_EXTRA_IMAGE_HOSTS
const extraHosts = String($env.SGCD_EXTRA_IMAGE_HOSTS ?? '').split(',').map((h) => h.trim().toLowerCase()).filter(Boolean);
const allowedHosts = ['res.cloudinary.com', 'api.telegram.org', ...extraHosts];
if (!allowedHosts.includes(hostname)) throw new Error(`validation: host no permitido (${hostname})`);
if (hostname === 'res.cloudinary.com' && !pathname.startsWith('/letiende/')) {
  throw new Error('validation: la URL de Cloudinary no es de la cuenta letiende');
}
if (hostname === 'api.telegram.org' && !pathname.startsWith('/file/bot')) {
  throw new Error('validation: la URL de Telegram no es de descarga de archivos');
}

return [{ json: { content_item_id: contentItemId, image_url: imageUrl, started_at: new Date().toISOString() } }];

// Abre la fila del paso en pipeline_steps ('started'); el intento es el último + 1
const { content_item_id, image_url, started_at } = $input.first().json;
const base = `${$env.SUPABASE_URL}/rest/v1/pipeline_steps`;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' };

const previous = await this.helpers.httpRequest({
  method: 'GET', url: base, headers, json: true,
  qs: { content_item_id: `eq.${content_item_id}`, step: 'eq.extract_visual', select: 'attempt', order: 'attempt.desc', limit: 1 },
});
const attempt = (previous?.[0]?.attempt ?? 0) + 1;

const created = await this.helpers.httpRequest({
  method: 'POST', url: base, json: true,
  headers: { ...headers, Prefer: 'return=representation' },
  body: { content_item_id, step: 'extract_visual', attempt, status: 'started', started_at, n8n_execution_id: String($execution.id) },
});
const row = Array.isArray(created) ? created[0] : created;
if (!row?.id) throw new Error('supabase: pipeline_steps no devolvió el id de la fila');

return [{ json: { content_item_id, image_url, started_at, step_id: row.id, attempt } }];

// Lee los bytes de la imagen (ADR-011: getBinaryDataBuffer, sin depender de dónde guarda n8n el binario)
const step = $('Registrar inicio').first().json;
if (!$input.first().binary?.data) throw new Error('download: la respuesta no trae un archivo');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

// Límite de inline_data (~20 MB por petición, con el base64 incluido)
const MAX_BYTES = 15 * 1024 * 1024;
if (buffer.length === 0 || buffer.length > MAX_BYTES) throw new Error(`download: tamaño fuera de rango (${buffer.length} bytes)`);

// El tipo sale de los bytes, no de la cabecera del servidor
const ascii = (start, end) => buffer.subarray(start, end).toString('latin1');
let mime = null;
if (buffer[0] === 0x89 && ascii(1, 4) === 'PNG') mime = 'image/png';
else if (buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) mime = 'image/jpeg';
else if (ascii(0, 4) === 'RIFF' && ascii(8, 12) === 'WEBP') mime = 'image/webp';
if (!mime) throw new Error('download: el archivo no es una imagen PNG, JPEG ni WebP');

return [{ json: { content_item_id: step.content_item_id, step_id: step.step_id, mime, image_bytes: buffer.length, image_b64: buffer.toString('base64') } }];

// Extracción visual estructurada con la API Interactions (mismo esquema y prompt que scripts/eval-gemini.mjs)
const THEMES = ["Libros", "Vinilos", "Teatro", "Fiestas", "Conciertos", "Conversatorios", "Proyecciones", "Presentaciones", "Café", "Comida", "Licores"];
const SYSTEM = `Eres el analista visual de Le Tiende, un centro cultural de Bogotá (librería, café, bar, teatro y vinilos). Describe SOLO lo que se ve en la imagen: no inventes títulos, autores, fechas ni lugares. Si un texto no se puede leer con claridad, usa null. Elige "tema" entre: ${THEMES.join(', ')}.`;
const USER = 'Analiza la imagen y devuelve el JSON pedido: tema, título visible, autor o artista visible, todo el texto legible y una descripción breve.';
const SCHEMA = {
  type: 'object',
  properties: {
    tema: { type: 'string', enum: THEMES },
    titulo: { type: ['string', 'null'] },
    autor_o_artista: { type: ['string', 'null'] },
    texto_visible: { type: 'array', items: { type: 'string' } },
    descripcion: { type: 'string' },
  },
  required: ['tema', 'titulo', 'autor_o_artista', 'texto_visible', 'descripcion'],
  additionalProperties: false,
};

const { content_item_id, step_id, mime, image_b64 } = $input.first().json;
const buildBody = (model) => ({
  model, system_instruction: SYSTEM, store: false,
  input: [{ type: 'text', text: USER }, { type: 'image', data: image_b64, mime_type: mime }],
  response_format: { type: 'text', mime_type: 'application/json', schema: SCHEMA },
  generation_config: { thinking_level: 'low', max_output_tokens: 8192 },
});


// Modelo principal y alterno (T-0025): ante 429/500/503 persistentes se prueba el alterno, que tiene cuota propia
const MODELS = ['gemini-3.5-flash-lite', 'gemini-3.1-flash-lite'];

// Hasta 3 reintentos por modelo con backoff 1 s, 2 s, 4 s; solo ante 429/500/503 o fallo de red
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
let response = null;
let lastError = '';
let attempts = 0;
let usedModel = MODELS[0];
let onlyQuota = true;
const t0 = Date.now();
outer: for (const model of MODELS) {
  usedModel = model;
  for (let retry = 0; retry <= 3; retry++) {
    if (retry > 0) await sleep(2 ** (retry - 1) * 1000);
    attempts++;
    try {
      response = await this.helpers.httpRequest({
        method: 'POST', url: 'https://generativelanguage.googleapis.com/v1beta/interactions',
        headers: { 'x-goog-api-key': $env.GEMINI_API_KEY, 'Content-Type': 'application/json' },
        body: buildBody(model), json: true, timeout: 120000, returnFullResponse: true, ignoreHttpStatusErrors: true,
      });
    } catch (e) {
      response = null;
      onlyQuota = false;
      lastError = `red (${model}): ${e.message}`;
      continue;
    }
    if (response.statusCode >= 200 && response.statusCode < 300) break outer;
    if (response.statusCode !== 429) onlyQuota = false;
    lastError = `HTTP ${response.statusCode} (${model}): ${String(response.body?.error?.message ?? '').slice(0, 300)}`;
    if (![429, 500, 503].includes(response.statusCode)) break outer; // 400/401/403/404: ni reintentar ni cambiar de modelo sirve
  }
}
const latency_ms = Date.now() - t0;

if (!response || response.statusCode < 200 || response.statusCode >= 300) {
  // 429 en todos los modelos: cuota del nivel gratuito agotada hasta el reinicio diario (ADR-013)
  if (response?.statusCode === 429 && onlyQuota) throw new Error(`waiting_quota: ${MODELS.join(' y ')} sin cuota tras ${attempts} intentos`);
  if (response?.statusCode === 401 || response?.statusCode === 403) throw new Error(`gemini_auth: ${lastError}`);
  throw new Error(`gemini_http: ${lastError} (${attempts} intentos)`);
}

const data = response.body ?? {};
const text = (data.steps ?? [])
  .filter((s) => s.type === 'model_output').flatMap((s) => s.content ?? [])
  .filter((c) => c.type === 'text').map((c) => c.text).join('');
let extraction;
try { extraction = JSON.parse(text); } catch (e) { throw new Error(`gemini_output: la respuesta no es JSON (${e.message})`); }

// El esquema ya lo exige la API; se revisa de nuevo porque el resto del flujo depende de estos campos
const isNullableString = (v) => v === null || typeof v === 'string';
if (!THEMES.includes(extraction?.tema) || !isNullableString(extraction.titulo) || !isNullableString(extraction.autor_o_artista)
  || !Array.isArray(extraction.texto_visible) || typeof extraction.descripcion !== 'string') {
  throw new Error('gemini_output: la extracción no cumple el esquema');
}

const usage = data.usage ?? {};
const tokens_input = usage.total_input_tokens ?? null;
const tokens_output = usage.total_output_tokens ?? null;
return [{ json: {
  content_item_id, step_id, model: usedModel, fallback_used: usedModel !== MODELS[0], extraction, latency_ms, attempts,
  usage: { input: tokens_input, output: tokens_output, thought: usage.total_thought_tokens ?? null },
  // Nivel gratuito sin facturación (ADR-013): costo 0
  step_patch: { status: 'succeeded', finished_at: new Date().toISOString(), model: usedModel, tokens_input, tokens_output, cost_usd: 0 },
} }];

// Normaliza el fallo de cualquier nodo para pipeline_steps, error_log y Telegram
const raw = $input.first().json;
const message = String(raw.error?.message ?? raw.error ?? raw.message ?? 'Error sin mensaje')
  // Nunca registrar el token del bot que va en las URLs de archivos de Telegram
  .replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***')
  .slice(0, 2000);
const prefix = (message.match(/^([a-z_]+):/) ?? [])[1];
// Sin prefijo propio (p. ej. un 404 del nodo HTTP), la etapa es el último nodo que llegó a ejecutarse
const stages = [['Registrar inicio', 'supabase'], ['Descargar imagen', 'download'], ['Preparar petición', 'download'],
  ['Llamar a Gemini', 'gemini'], ['Cerrar paso exitoso', 'supabase']];
const stage = stages.filter(([node]) => $(node).isExecuted).pop()?.[1];
const error_type = prefix ?? stage ?? 'execution_error';

// Desde una rama de error, first() sin argumentos lee la salida 1 (error) del nodo: hay que pedir la salida 0
const input = $('Entrada').first(0, 0)?.json ?? {};
// Si 'Registrar inicio' no corrió o falló, no hay fila abierta en pipeline_steps
const step = $('Registrar inicio').isExecuted ? ($('Registrar inicio').first(0, 0)?.json ?? null) : null;
const contentItemId = /^[0-9a-f-]{36}$/i.test(String(input.content_item_id ?? '')) ? String(input.content_item_id).toLowerCase() : null;
const status = error_type === 'waiting_quota' ? 'waiting_quota' : 'failed';

return [{ json: {
  has_step: Boolean(step?.step_id),
  step_id: step?.step_id ?? null,
  step_patch: { status, finished_at: new Date().toISOString(), error_type, error_message: message },
  error_log_row: {
    workflow: '10-extraer-visual', content_item_id: contentItemId, error_type, error_message: message,
    stack_trace: JSON.stringify({ execution_id: $execution.id, error: raw.error ?? raw }).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').slice(0, 8000),
  },
  telegram_text: `⚠️ 10 - Extraer visual (${error_type})\nItem: ${contentItemId ?? 'sin id válido'}\nEjecución: ${$execution.id}\n\n${message.slice(0, 500)}`,
  result: { ok: false, content_item_id: contentItemId, status, error_type, error_message: message },
} }];
